source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && export REQUESTS_CA_BUNDLE=/etc/ssl/certs/ca-certificates.crt && python3 -c "
import requests
r = requests.get('https://modelscope.cn/api/v1/models', params={'Query': 'nli', 'PageSize': 20}, verify=False, timeout=15)
if r.ok:
    data = r.json()
    models = data.get('Data', {}).get('Models', [])
    for m in models:
        name = m.get('Name','')
        path = m.get('Path','')
        if 'nli' in name.lower() or 'mnli' in name.lower() or 'entail' in name.lower():
            print(f'{path}: {name}')
    if not models:
        print('No models found')
else:
    print(f'Error: {r.status_code}')
" 2>&1
